using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithPromptsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();
app.MapMcp();
app.MapGet("/health", () => "ok");
app.Run();

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Reads a configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app.name"] = "ConfigMcpServer",
            ["app.version"] = "1.0.0",
            ["app.environment"] = "production",
            ["app.max_connections"] = "100"
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Full application configuration as JSON")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            Environment = "production",
            MaxConnections = 100,
            Features = new { EnableCaching = true, EnableLogging = true }
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features/{featureName}", Name = "Feature Flag",
        MimeType = "application/json"), Description("Gets a specific feature flag status")]
    public static string GetFeatureFlag(
        [Description("Name of the feature flag")] string featureName)
    {
        var features = new Dictionary<string, bool>
        {
            ["caching"] = true,
            ["logging"] = true,
            ["dark_mode"] = false,
            ["beta_features"] = false
        };

        var result = new
        {
            Feature = featureName,
            Enabled = features.GetValueOrDefault(featureName, false),
            Exists = features.ContainsKey(featureName)
        };

        return JsonSerializer.Serialize(result);
    }
}

